            aWandererG = aWandererG + ((((RotL64(aScatter, 23U) + aOrbiterE) + RotL64(aOrbiterI, 39U)) + RotL64(aCarry, 27U)) + aWUSaltH[(((511U - aIndex) + 485U)) & S_SALT1]);
            aWandererD = aWandererD ^ (((RotL64(aIngress, 19U) + aOrbiterI) + RotL64(aOrbiterK, 27U)) + aWUSaltA[((aIndex + 501U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aCross, 29U) + aOrbiterC) + RotL64(aOrbiterB, 20U));
            aWandererC = aWandererC ^ (((RotL64(aIngress, 37U) + RotL64(aOrbiterJ, 53U)) + aOrbiterC) + aWUSaltD[((aIndex + 189U)) & S_SALT1]);
