            aOrbiterH = (((aWandererF + RotL64(aCross, 60U)) + RotL64(aCarry, 13U)) + 0x01D0EB24F5A975AFULL) + aOASaltF[((aIndex + 379U)) & S_SALT1];
            aOrbiterK = (((aWandererB + RotL64(aPrevious, 11U)) + RotL64(aCarry, 29U)) + 0xC43D05E75AE63B10ULL) + aOASaltD[(((511U - aIndex) + 315U)) & S_SALT1];
