            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xACA33E357225B9D5ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x54BE0A73482F33BAULL;
            aOrbiterA = RotL64((aOrbiterA * 0xAB49DA7BA54FB371ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x2B24E0AA410E396FULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterH) ^ 0xD727614559709ADDULL) ^ aOUSaltB[(((511U - aIndex) + 192U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xBF6DCEB6CDCB6AF1ULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xFBEE1B6F80ABD132ULL) + aOUSaltD[((aIndex + 365U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x6FA4B51BE48BE38BULL) ^ aOUSaltC[((aIndex + 271U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x63E8DD0D0119265DULL), 39U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xFDFD0E12D9C3AB38ULL;
