            aOrbiterB = ((aWandererK + RotL64(aCross, 5U)) + RotL64(aCarry, 37U)) + 0xFCF83CCA56A2BD0AULL;
            aOrbiterH = (((aWandererC + RotL64(aScatter, 35U)) + RotL64(aCarry, 23U)) + 0x958430BE0F3E6405ULL) + aOASaltB[((aIndex + 51U)) & S_SALT1];
