    std::uint64_t *aOUSaltB = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltB;
    std::uint64_t *aOUSaltC = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterUpdate.mSaltC;
