            //
            aScatter = (RotL64(aPrevious, 57U) ^ RotL64(aCross, 29U)) + (RotL64(aCarry, 5U) ^ RotL64(aIngress, 44U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = (aWandererF + RotL64(aScatter, 13U)) + 0x6A6F1E0891BAF7DBULL;
            aOrbiterB = (((aWandererK + RotL64(aIngress, 39U)) + RotL64(aCarry, 23U)) + 0xDBD51A5867C8953AULL) + aOASaltH[(((511U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = (((aWandererJ + RotL64(aPrevious, 29U)) + RotL64(aCarry, 37U)) + 0x5A7D0F13AD7B1554ULL) + aOASaltA[((aIndex + 170U)) & S_SALT1];
