            aWandererE = aWandererE + ((((RotL64(aPrevious, 39U) + aOrbiterK) + RotL64(aOrbiterE, 43U)) + RotL64(aCarry, 47U)) + aWUSaltC[((aIndex + 147U)) & S_SALT1]);
