            aIngress ^= (RotL64(aSoilLaneA[((aIndex + 13954U)) & S_BLOCK1], 39U) ^ RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 12914U)) & S_BLOCK1], 54U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
