            aWandererA = aWandererA + (((RotL64(aIngress, 39U) + RotL64(aOrbiterE, 47U)) + aOrbiterH) + aWUSaltE[((aIndex + 137U)) & S_SALT1]);
            aWandererD = aWandererD ^ ((RotL64(aScatter, 28U) + aOrbiterA) + RotL64(aOrbiterG, 22U));
            aWandererJ = aWandererJ + ((((RotL64(aCross, 51U) + RotL64(aOrbiterA, 11U)) + aOrbiterK) + RotL64(aCarry, 53U)) + aWUSaltD[((aIndex + 439U)) & S_SALT1]);
