            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x56D3B73F9B13AA0CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x181E0221396586E5ULL) ^ aOUSaltB[((aIndex + 143U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x861BB212D4D9E557ULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x85E2218D6BDA0834ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x6E97389F2DEB162EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xFCBA9B36BDE9A4CDULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xD87A9788B41D36A1ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterD) ^ 0xDF51D6BE5E5C872EULL) ^ aOUSaltC[((aIndex + 483U)) & S_SALT1];
