            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterJ, 5U));
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterH, 13U));
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterE, 51U));
            aIngress = aIngress + RotL64(aOrbiterK, 56U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererI = aWandererI ^ ((RotL64(aIngress, 42U) + aOrbiterK) + RotL64(aOrbiterE, 35U));
            aWandererH = aWandererH + ((RotL64(aScatter, 23U) + RotL64(aOrbiterD, 43U)) + aOrbiterH);
