            aWandererC = aWandererC ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterB, 21U)) + aOrbiterI);
            aWandererG = aWandererG + (((RotL64(aCross, 51U) + aOrbiterC) + RotL64(aOrbiterG, 29U)) + RotL64(aCarry, 51U));
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 21U) + RotL64(aOrbiterA, 53U)) + aOrbiterK) + aWUSaltF[((aIndex + 501U)) & S_SALT1]);
