            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterH, 27U)) + aOrbiterA);
            aWandererF = aWandererF + (((RotL64(aCross, 35U) + RotL64(aOrbiterF, 41U)) + aOrbiterJ) + aWUSaltD[((aIndex + 213U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 6U) + aOrbiterB) + RotL64(aOrbiterD, 47U));
            //
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererG, 41U));
