            aOrbiterB = (((aWandererK + RotL64(aPrevious, 3U)) + RotL64(aCarry, 41U)) + 0xA6834075A8D10B2AULL) + aOASaltD[(((511U - aIndex) + 50U)) & S_SALT1];
