            aOrbiterA = (((aWandererE + RotL64(aPrevious, 60U)) + RotL64(aCarry, 13U)) + 0x1C22271C96AA027CULL) + aOASaltG[(((511U - aIndex) + 195U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x49CD43111EC59051ULL;
