            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0xD4ED96BB87CC29E0ULL) + aOUSaltD[((aIndex + 372U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x36F4F4972EDB939CULL;
