            aOrbiterE = RotL64((aOrbiterE * 0x433048AADE0EE79FULL), 29U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0x8E95072316A0DCA3ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xB8FA1CFE93B5AD4EULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBE5E565176C31097ULL), 3U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterF) + 0xBBCE1F3958B44334ULL) + aOUSaltA[(((511U - aIndex) + 508U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x5673D1DF250B8F01ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x83F7E70D09D14339ULL), 21U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0x1E2E93B42EDAE4BBULL) + aOUSaltC[(((511U - aIndex) + 84U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x3AE674D85514F64EULL) ^ aOUSaltE[(((511U - aIndex) + 131U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xE8EB455C50B6516DULL), 13U);
