            aWandererG = aWandererG + ((((RotL64(aPrevious, 29U) + RotL64(aOrbiterA, 57U)) + aOrbiterE) + RotL64(aCarry, 3U)) + aWUSaltF[((aIndex + 415U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 41U) + aOrbiterB) + RotL64(aOrbiterD, 41U)) + aWUSaltE[((aIndex + 92U)) & S_SALT1]);
