            aWandererE = aWandererE ^ (((RotL64(aIngress, 19U) + aOrbiterC) + RotL64(aOrbiterA, 29U)) + aWUSaltE[(((511U - aIndex) + 195U)) & S_SALT1]);
            aWandererC = aWandererC + ((RotL64(aScatter, 23U) + RotL64(aOrbiterD, 41U)) + aOrbiterB);
