            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x0905092B271EF96CULL) + aOUSaltG[((aIndex + 234U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterC) ^ 0x7EE0E55F38C54717ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x19DD5B7C9BCF59A1ULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x54CC8E038BF015EBULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterA) ^ 0xA442677677582C2DULL;
            aOrbiterK = RotL64((aOrbiterK * 0x17031478CF73A479ULL), 53U);
